theorem extracted_1.{u_2} {G : Type u_2} [inst : AddCommGroup G] {G₂ : AddSubgroup G} (H' : AddSubgroup (G ⧸ G₂)) :
  let H := G ⧸ G₂;
  let φ := mk' G₂;
  let N := AddSubgroup.comap φ H';
  G₂ ≤ N := sorry

theorem extracted_1.{u_2} {G : Type u_2} [inst : AddCommGroup G] {G₂ : AddSubgroup G} (H' : AddSubgroup (G ⧸ G₂)) :
  let H := G ⧸ G₂;
  let φ := mk' G₂;
  let N := AddSubgroup.comap φ H';
  G₂ ≤ N →
    let H := G ⧸ G₂;
    let φ := mk' G₂;
    let N := AddSubgroup.comap φ H';
    ∃ e, ∀ (x : G), e ((mk' H') (φ x)) = (mk' N) x := sorry

theorem extracted_1.{u_2} {G : Type u_2} [inst : AddCommGroup G] {G₂ : AddSubgroup G} (H' : AddSubgroup (G ⧸ G₂)) :
  let H := G ⧸ G₂;
  let φ := mk' G₂;
  let N := AddSubgroup.comap φ H';
  G₂ ≤ N →
    let H'' := AddSubgroup.map (mk' G₂) N;
    H' = H'' := sorry

theorem extracted_1.{u_2} {G : Type u_2} [inst : AddCommGroup G] {G₂ : AddSubgroup G} (H' : AddSubgroup (G ⧸ G₂)) :
  let H := G ⧸ G₂;
  let φ := mk' G₂;
  let N := AddSubgroup.comap φ H';
  G₂ ≤ N →
    let H'' := AddSubgroup.map (mk' G₂) N;
    H' = H'' →
      let H := G ⧸ G₂;
      let φ := mk' G₂;
      let N := AddSubgroup.comap φ H';
      ∃ e, ∀ (x : G), e ((mk' H') (φ x)) = (mk' N) x := sorry

theorem extracted_1.{u_1} {G : Type u_1} [inst : AddCommGroup G] {A B : Set G} (x : G) (hx : x ∈ A) (y : G)
  (hy : y ∈ B) :
  let G' := AddSubgroup.closure (A - A ∪ (B - B));
  G' = AddSubgroup.closure (A - A ∪ (B - B)) →
    let A' := Subtype.val ⁻¹' (-x +ᵥ A);
    A' = Subtype.val ⁻¹' (-x +ᵥ A) →
      let B' := Subtype.val ⁻¹' (-y +ᵥ B);
      B' = Subtype.val ⁻¹' (-y +ᵥ B) → -x +ᵥ A ⊆ range Subtype.val := sorry

