    A' = Subtype.val ⁻¹' (-x +ᵥ A) →
      let B' := Subtype.val ⁻¹' (-y +ᵥ B);
      B' = Subtype.val ⁻¹' (-y +ᵥ B) →
        -x +ᵥ A ⊆ range Subtype.val →
          ∃ G' A' B', IsShift A (Subtype.val '' A') ∧ IsShift B (Subtype.val '' B') ∧ NotInCoset A' B' := sorry

